"""Repair only capsule dependencies after all scheduled model runs are complete."""
import sys,json,shutil,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];META=ROOT/'benchmarks/rtx_trajectory_cost_v4'
sys.path.insert(0,str(META))
import FAN_AMENDMENT_ARCHIVE_RECOVERY as recovery
import FAN_CAPSULE_DEPENDENCIES_V3 as dependencies
from prepare import save,sha,now
import package,guards,verify_joint,closeout
OUT=ROOT/'work/fan-amendment/capsule-dependencies-recovery1'
ORIGINAL_PUBLISH=package.publish

def publish(stage,mode,arm,anonymous=False):
    if mode=='complete':dependencies.augment(stage,package.longpath(ROOT),anonymous)
    return ORIGINAL_PUBLISH(stage,mode,arm,anonymous)
package.publish=publish
import anonymous as anonymous_module
ORIGINAL_ANONYMOUS_MAKE=anonymous_module.make

def anonymous_make(original,mode,arm):
    safe=package.longpath(ROOT/'work'/('anonymous-input-'+arm+'-'+mode+'-fan-dependencies'))
    # Optional author-side archive assembly code is not needed by either frozen
    # offline verifier. Its public identity-test labels trigger the conservative
    # derivative privacy scan, so omit this one control utility from the input.
    # Keep every raw observation and all original numerical/verifier sources.
    shutil.copytree(original,safe,ignore=shutil.ignore_patterns('FAN_CAPSULE_DEPENDENCIES_V3.py'))
    dependencies.augment(safe,package.longpath(ROOT),False)
    save(safe/'metadata/ANONYMOUS_FAN_DEPENDENCY_SCOPE.json',{'scope':'Copy unchanged shared predictor/host provenance, redact with the original frozen anonymizer, then restore the redacted host member at its canonical verifier path.','optional_author_only_control_omitted':'FAN_CAPSULE_DEPENDENCIES_V3.py','original_numerical_and_verifier_sources_changed':False,'raw_observations_omitted':False,'original_host_identity_added_after_redaction':False})
    return ORIGINAL_ANONYMOUS_MAKE(safe,mode,arm)
anonymous_module.make=anonymous_make

def preserve(path,label):
    path=package.longpath(path)
    if not path.exists():return
    target=package.longpath(ROOT/'work/fan-archive-attempts/complete-dependencies-attempt1'/label)
    # Validate ordinary absolute forms before native long-path filesystem moves.
    for p in [path,target]:Path(str(p).removeprefix('\\\\?\\')).resolve().relative_to(ROOT.resolve())
    assert not target.exists();target.parent.mkdir(parents=True,exist_ok=True);path.rename(target)

def remove_failed_transport():
    good=set()
    for p in META.glob('*_ARCHIVE.json'):
        value=json.loads(p.read_text(encoding='utf-8'))
        if value.get('offline_reconstruction',{}).get('status')=='PASS':good.add(value['path'])
    for arm,folder in package.ART.items():
        for index in list(folder.glob('complete*.parts.json')):
            if index.relative_to(package.ROOT).as_posix() in good:continue
            value=json.loads(index.read_text(encoding='utf-8'))
            for part in value['parts']:preserve(index.parent/part['name'],arm+'/'+part['name'])
            preserve(index,arm+'/'+index.name)
            preserve(ROOT/'work'/('clean-'+arm+'-'+value['sha256'][:16]),'clean-'+arm+'-'+value['sha256'][:16])
    for arm in ['A','B']:
        if not (META/(arm+'_COMPLETE_ARCHIVE.json')).exists():preserve(ROOT/'work'/('package-stage-'+arm+'-complete'),'package-stage-'+arm+'-complete')
        if not (META/(arm+'_COMPLETE_ANONYMOUS_ARCHIVE.json')).exists():preserve(ROOT/'work'/('anonymous-stage-'+arm+'-complete'),'anonymous-stage-'+arm+'-complete')

def make_arm(arm):
    author=META/(arm+'_COMPLETE_ARCHIVE.json');anon=META/(arm+'_COMPLETE_ANONYMOUS_ARCHIVE.json')
    if not author.exists():
        package.make('complete',arm);return
    if anon.exists():return
    derived=package.longpath(ROOT/'work'/('capsule-'+arm+'-author-derived-input'))
    shutil.copytree(package.longpath(ROOT/'work'/('package-stage-'+arm+'-complete')),derived)
    dependencies.augment(derived,package.longpath(ROOT),False)
    for name in ['FAN_CAPSULE_DEPENDENCIES_V3.py','FAN_CAPSULE_RECOVERY.json']:
        shutil.copy2(META/name,derived/'metadata'/name)
    import anonymous
    anonymous.make(derived,'complete',arm)

def run():
    for name,total in [('A-live',57),('B-formal',171)]:
        data=json.loads((ROOT/'work'/name/'records.json').read_text(encoding='utf-8'))
        assert data['status']=='COMPLETE' and len(data['runs'])==total and all(r['status']=='VALID' for r in data['runs'])
    prior=json.loads((ROOT/'work/fan-amendment/transport-recovery1/records.json').read_text(encoding='utf-8'))
    assert prior['status']=='STOPPED_PRESERVED_FOR_REVIEW'
    assert json.loads((META/'CLOSEOUT.json').read_text(encoding='utf-8'))['status']=='FORMAL_COMPLETE'
    for stage in ['F0','F1','F2','FAN_AMENDMENT','B_START']:guards.check_manifest(stage+'_MANIFEST.json');guards.receipt(stage)
    OUT.mkdir(parents=True,exist_ok=False)
    record={'status':'STARTED','started_utc':now(),'formal_model_retries':0,'model_arrays_changed':0,'stages':[]};save(OUT/'records.json',record)
    save(META/'FAN_CAPSULE_RECOVERY.json',{'utc':now(),'scope':'Derived capsule dependency correction only. No source/parameter change to any model run, no model retry, no weakening of independent verifier assertions. Passed author capsules retained unchanged. Original failed capsule transport and stages preserved.','original_stop_record':prior,'dependency_adapter_source_sha256':sha(META/'FAN_CAPSULE_DEPENDENCIES_V3.py'),'dependency_adapter_source_path':'FAN_CAPSULE_DEPENDENCIES_V3.py','operator_source_utf8':Path(__file__).read_text(encoding='utf-8'),'fresh_B_conditions':171,'copied_A_predictors_are_B_provenance_only':True,'formal_model_retries':0})
    try:
        for name,fn in [('preserve-failed-capsules',remove_failed_transport),('complete-A-capsules',lambda:make_arm('A')),('complete-B-capsules',lambda:make_arm('B')),('independent-joint-verification',lambda:verify_joint.all_reached(ROOT)),('complete-index',closeout.index)]:
            row={'stage':name,'started_utc':now(),'status':'STARTED'};record['stages'].append(row);save(OUT/'records.json',record);print('START',name,flush=True)
            fn();row.update(status='PASS',ended_utc=now());save(OUT/'records.json',record);print('PASS',name,flush=True)
        record['status']='COMPLETE'
    except Exception as error:record.update(status='STOPPED_PRESERVED_FOR_REVIEW',error=repr(error));raise
    finally:record['ended_utc']=now();save(OUT/'records.json',record)
if __name__=='__main__':run()
